import { checkDiscount } from './cart-api';
import type { Cart } from './models/cart';
import type { CartItem } from './models/cart-item';

export function emptyCart(): Cart {
  return { items: [] };
}

export function addItem(cart: Cart, item: CartItem): Cart {
  const existing = cart.items.find((i) => i.productId === item.productId);
  if (!existing) return { ...cart, items: [...cart.items, item] };
  return {
    ...cart,
    items: cart.items.map((i) =>
      i.productId === item.productId ? { ...i, quantity: i.quantity + item.quantity } : i,
    ),
  };
}

export function removeItem(cart: Cart, productId: string): Cart {
  return { ...cart, items: cart.items.filter((i) => i.productId !== productId) };
}

export async function applyDiscount(cart: Cart, code: string): Promise<Cart> {
  const percent = await checkDiscount(code);
  return { ...cart, discount: { code, percent } };
}
EOF
