import type { Cart } from './models/cart';
import type { CartItem } from './models/cart-item';

export function lineTotalCents(item: CartItem): number {
  return item.unitPriceCents * item.quantity;
}

export function subtotalCents(cart: Cart): number {
  return cart.items.reduce((sum, item) => sum + lineTotalCents(item), 0);
}

export function discountCents(cart: Cart): number {
  return Math.round((subtotalCents(cart) * (cart.discount?.percent ?? 0)) / 100);
}

export function totalCents(cart: Cart): number {
  return subtotalCents(cart) - discountCents(cart);
}
EOF
